import os
import re
from pathlib import Path
from datetime import date

import pytesseract
from PIL import Image
from openpyxl import Workbook

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

TIERS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE',
     'NETT TOTAL', 'NET TOTAL'],
]
EXCLUSIONS = [
    'SUBTOTAL', 'SUB TOTAL',
    'TAX', 'GST', 'SST',
    'DISCOUNT', 'CHANGE', 'CASH TENDERED',
]
AMOUNT_RE = re.compile(r'(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.\d])')


def extract_total_from_text(text):
    lines = text.splitlines()
    best = None  # (tier, value)
    for li, line in enumerate(lines):
        U = line.upper()
        if any(k in U for k in EXCLUSIONS):
            continue
        for ti, kws in enumerate(TIERS):
            if any(k in U for k in kws):
                amounts = [float(m.group(1).replace(',', '')) for m in AMOUNT_RE.finditer(line)]
                if amounts:
                    val = amounts[-1]
                elif 'TOTAL' in U:
                    val = None
                    for look in range(li + 1, min(li + 3, len(lines))):
                        nxt = lines[look]
                        if not nxt.strip():
                            continue
                        NU = nxt.upper()
                        if any(k in NU for k in EXCLUSIONS):
                            continue
                        nx = [float(m.group(1).replace(',', '')) for m in AMOUNT_RE.finditer(nxt)]
                        if nx:
                            val = nx[-1]
                            break
                else:
                    val = None
                if val is not None:
                    if best is None or ti < best[0]:
                        best = (ti, val)
                break
    return f'{best[1]:.2f}' if best else None


DATE_PATTERNS = [
    (re.compile(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})(?!\d)'), 'dmy4'),
    (re.compile(r'(?<!\d)(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})(?!\d)'), 'ymd'),
    (re.compile(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)'), 'dmy2'),
    (re.compile(r'(?<!\w)(\d{1,2})[\s/\-](Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[\s/\-](\d{4})', re.I), 'dmony'),
]
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}


def _valid(y, mo, d):
    try:
        date(y, mo, d)
        return 2000 <= y <= 2099
    except Exception:
        return False


def extract_date_from_text(text):
    lines = text.splitlines()
    scored = []
    for i, ln in enumerate(lines):
        boost = 1 if re.search(r'date|tarikh|inv', ln, re.I) else 0
        scored.append((boost, i, ln))
    scored.sort(key=lambda x: (-x[0], x[1]))
    for _, _, ln in scored:
        for rx, kind in DATE_PATTERNS:
            for m in rx.finditer(ln):
                if kind == 'dmy4':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    if mo > 12 and d <= 12:
                        d, mo = mo, d
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + yy if yy <= 49 else 1900 + yy
                elif kind == 'dmony':
                    d = int(m.group(1))
                    mo = MONTHS[m.group(2).lower()[:3]]
                    y = int(m.group(3))
                if _valid(y, mo, d):
                    return f'{y:04d}-{mo:02d}-{d:02d}'
    return None


def main():
    files = sorted(p.name for p in IMG_DIR.iterdir()
                   if p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'})
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for name in files:
        text = pytesseract.image_to_string(Image.open(IMG_DIR / name))
        d = extract_date_from_text(text)
        t = extract_total_from_text(text)
        print(name, d, t)
        row_idx = ws.max_row + 1
        ws.cell(row=row_idx, column=1, value=name)
        ws.cell(row=row_idx, column=2, value=d)
        cell = ws.cell(row=row_idx, column=3, value=t)
        if t is not None:
            cell.number_format = '@'
    wb.save(OUT_PATH)


if __name__ == '__main__':
    main()
